<!doctype html><html lang="en"><head><meta charset="utf-8"><title>{{ $invoice->number }} · Dropbell</title><style>body{font-family:Arial,sans-serif;color:#061b50;max-width:900px;margin:40px auto;padding:24px}h1{color:#0055e8}table{border-collapse:collapse;width:100%;margin:30px 0}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}p{line-height:1.6}.totals{text-align:right}small{color:#556580}@media print{body{margin:0}}</style></head><body>@php($order=$snapshot['order']) @php($address=json_decode($order['delivery_address'],true))<h1>dropbell</h1><h2>Order invoice {{ $invoice->number }}</h2><p>Order: {{ $order['reference'] }}<br>Placed: {{ $order['created_at'] }}<br>Invoice issued: {{ $invoice->created_at }}</p><h3>Delivered to</h3><p>{{ $address['name'] }}<br>{{ $address['street'] }}<br>{{ $address['city'] }} — {{ $address['pin'] }}<br>{{ $address['phone'] }}</p><table><thead><tr><th>Item</th><th>Vendor</th><th>Pack</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>@foreach($snapshot['items'] as $item)<tr><td>{{ $item['product_name'] }}</td><td>{{ $item['vendor_name'] ?: 'Dropbell' }}</td><td>{{ $item['pack_size'] }}</td><td>{{ $item['quantity'] }}</td><td>INR {{ number_format($item['unit_price_paise']/100,2) }}</td><td>INR {{ number_format($item['quantity']*$item['unit_price_paise']/100,2) }}</td></tr>@endforeach</tbody></table><div class="totals"><p>Items: INR {{ number_format($order['subtotal_paise']/100,2) }}<br>Discount: INR {{ number_format($order['discount_paise']/100,2) }}<br>Delivery: INR {{ number_format($order['delivery_paise']/100,2) }}</p><h2>Total: INR {{ number_format($order['total_paise']/100,2) }}</h2></div><small>This order invoice records the purchase summary. Supplier tax invoices, where applicable, are provided by the vendors. Open this file in a browser to print or save as PDF.</small></body></html>
